async function copyAcademicText(value,button){
  let ok=false;
  try{
    if(navigator.clipboard&&window.isSecureContext){
      await navigator.clipboard.writeText(value);
      ok=true;
    }
  }catch(_){}
  if(!ok){
    const ta=document.createElement('textarea');
    ta.value=value;
    ta.setAttribute('readonly','');
    ta.style.position='fixed';
    ta.style.opacity='0';
    document.body.appendChild(ta);
    ta.select();
    try{ok=document.execCommand('copy')}catch(_){}
    ta.remove();
  }
  const feedback=document.getElementById('copyFeedback');
  if(feedback){
    feedback.textContent=ok?(lang==='en'?'Email copied to clipboard.':'Email berhasil disalin.'):(lang==='en'?'Unable to copy automatically.':'Tidak dapat menyalin secara otomatis.');
    feedback.classList.add('show');
    clearTimeout(copyAcademicText._timer);
    copyAcademicText._timer=setTimeout(()=>feedback.classList.remove('show'),1800);
  }
  if(ok&&button){
    const label=button.querySelector('span');
    if(label){
      const original=label.textContent;
      label.textContent=lang==='en'?'Copied ✓':'Tersalin ✓';
      setTimeout(()=>{if(document.contains(label))label.textContent=original},1400);
    }
  }
}
